class RuntimeProfile(str, Enum):
    """冻结于 Composition Root 的运行用途；不能由请求覆盖。"""

    PRODUCTION = "PRODUCTION"
    EPISODIC_EVALUATION_LAYER1 = "EPISODIC_EVALUATION_LAYER1"

    @classmethod
    def parse(cls, value: object) -> "RuntimeProfile":
        if value is None:
